65	/**
66	 * A parser to parse simple language as a Camel {@link Predicate}
67	 */
68	public class SimplePredicateParser extends BaseSimpleParser {
69	
70	    // use caches to avoid re-parsing the same expressions over and over again
71	    private final Map<String, Expression> cacheExpression;
72	    private boolean skipFileFunctions;
73	
74	    public SimplePredicateParser(CamelContext camelContext, String expression,
75	                                 boolean allowEscape,
76	                                 Map<String, Expression> cacheExpression) {
77	        this(camelContext, expression, allowEscape, false, cacheExpression);
78	    }
79	
80	    public SimplePredicateParser(CamelContext camelContext, String expression,
81	                                 boolean allowEscape, boolean skipFileFunctions,
82	                                 Map<String, Expression> cacheExpression) {
83	        super(camelContext, expression, allowEscape);
84	        this.cacheExpression = cacheExpression;
85	        this.skipFileFunctions = skipFileFunctions;
86	    }
87	
88	    public Predicate parsePredicate() {
89	        try {
90	            Expression init = null;
91	            // are there init block then parse this part only, and change the expression to clip out the init block afterwards
92	            if (SimpleInitBlockTokenizer.hasInitBlock(expression)) {
93	                SimpleInitBlockParser initParser
94	                        = new SimpleInitBlockParser(camelContext, expression, allowEscape, skipFileFunctions, cacheExpression);
95	                init = initParser.parseExpression();
96	                if (init != null) {
97	                    String part = StringHelper.after(expression, SimpleInitBlockTokenizer.INIT_END);
98	                    if (part.startsWith("\n")) {
99	                        // skip newline after ending init block
100	                        part = part.substring(1);
101	                    }
102	                    this.expression = part;
103	                    // use $$key as local variable in the expression afterwards.
104	                    // Sort by descending length so a longer key (e.g. "$ab") is replaced before any
105	                    // shorter prefix (e.g. "$a"), preventing "$ab" from becoming "${variable.a}b".
106	                    List<String> sortedKeys = new ArrayList<>(initParser.getInitKeys());
107	                    sortedKeys.sort(Comparator.comparingInt(String::length).reversed());
108	                    for (String key : sortedKeys) {
109	                        this.expression = this.expression.replace("$" + key, "${variable." + key + "}");
110	                    }
111	                }
112	            }
113	
114	            parseTokens();
115	            Predicate pre = doParsePredicate();
116	            // include init block in expression
117	            if (init != null) {
118	                pre = PredicateBuilder.and(PredicateBuilder.alwaysTrue(init), pre);
119	            }
120	            return pre;
121	        } catch (SimpleParserException e) {
122	            // catch parser exception and turn that into a syntax exceptions
123	            throw new SimpleIllegalSyntaxException(expression, e.getIndex(), e.getMessage(), e);
124	        } catch (Exception e) {
125	            // include exception in rethrown exception
126	            throw new SimpleIllegalSyntaxException(expression, -1, e.getMessage(), e);
127	        }
128	    }
129	
130	    public String parseCode() {
131	        try {
132	            parseTokens();
133	            return doParseCode();
134	        } catch (SimpleParserException e) {
135	            // catch parser exception and turn that into a syntax exceptions
136	            throw new SimpleIllegalSyntaxException(expression, e.getIndex(), e.getMessage(), e);
137	        } catch (Exception e) {
138	            // include exception in rethrown exception
139	            throw new SimpleIllegalSyntaxException(expression, -1, e.getMessage(), e);
140	        }
141	    }
142	
143	    /**
144	     * First step parsing into a list of nodes.
145	     *
146	     * This is used as SPI for camel-csimple to do AST transformation and parse into java source code.
147	     */
148	    public List<SimpleNode> parseTokens() {
149	        clear();
150	        // parse using the following grammar
151	        nextToken();
152	        while (!token.getType().isEol()) {
153	            // predicate supports quotes, functions, operators and whitespaces
154	            if (!singleQuotedLiteralWithFunctionsText()
155	                    && !doubleQuotedLiteralWithFunctionsText()
156	                    && !functionText()
157	                    && !unaryOperator()
158	                    && !binaryOperator()
159	                    && !ternaryOperator()
160	                    && !chainOperator()
161	                    && !otherOperator()
162	                    && !logicalOperator()
163	                    && !isBooleanValue()
164	                    && !token.getType().isWhitespace()
165	                    && !token.getType().isEol()) {
166	                // okay the symbol was not one of the above, so its not supported
167	                // use the previous index as that is where the problem is
168	                throw new SimpleParserException("Unexpected token " + token, previousIndex);
169	            }
170	            // take the next token
171	            nextToken();
172	        }
173	
174	        // now after parsing we need a bit of work to do, to make it easier to turn the tokens
175	        // into and ast, and then from the ast, to Camel predicate(s).
176	        // hence why there is a number of tasks going on below to accomplish this
177	
178	        // remove any ignorable white space tokens
179	        removeIgnorableWhiteSpaceTokens();
180	        // turn the tokens into the ast model
181	        parseTokensAndCreateNodes();
182	        // compact and stack blocks (eg function start/end, quotes start/end, etc.)
183	        prepareBlocks(nodes);
184	        // compact and stack unary expressions
185	        prepareUnaryExpressions(nodes);
186	        // compact and stack chain expressions
187	        prepareChainExpression(nodes);
188	        // compact and stack binary expressions
189	        prepareBinaryExpressions(nodes);
190	        // compact and stack ternary expressions
191	        prepareTernaryExpressions(nodes);
192	        // compact and stack other expressions
193	        prepareOtherExpressions(nodes);
194	        // compact and stack logical expressions
195	        prepareLogicalExpressions(nodes);
196	
197	        return nodes;
198	    }
199	
200	    /**
201	     * Second step parsing into a predicate
202	     */
203	    protected Predicate doParsePredicate() {
204	        // create and return as a Camel predicate
205	        List<Predicate> predicates = createPredicates();
206	        if (predicates.isEmpty()) {
207	            // return a false predicate as response as there was nothing to parse
208	            return PredicateBuilder.constant(false);
209	        } else if (predicates.size() == 1) {
210	            return predicates.get(0);
211	        } else {
212	            return PredicateBuilder.and(predicates);
213	        }
214	    }
215	
216	    /**
217	     * Second step parsing into code
218	     */
219	    protected String doParseCode() {
220	        StringBuilder sb = new StringBuilder(256);
221	        for (SimpleNode node : nodes) {
222	            String exp = node.createCode(camelContext, expression);
223	            SimpleExpressionParser.parseLiteralNode(sb, node, exp);
224	        }
225	        String code = sb.toString();
226	        code = code.replace(BaseSimpleParser.CODE_START, "");
227	        code = code.replace(BaseSimpleParser.CODE_END, "");
228	        return code;
229	    }
230	
231	    /**
232	     * Parses the tokens and crates the AST nodes.
233	     * <p/>
234	     * After the initial parsing of the input (input -> tokens) then we parse again (tokens -> ast).
235	     * <p/>
236	     * In this parsing the balance of the blocks is checked, so that each block has a matching start and end token. For
237	     * example a single quote block, or a function block etc.
238	     */
239	    protected void parseTokensAndCreateNodes() {
240	        // we loop the tokens and create a sequence of ast nodes
241	
242	        // we need to keep a bit of state for keeping track of single and double quotes
243	        // which need to be balanced and have matching start/end pairs
244	        SimpleNode lastSingle = null;
245	        SimpleNode lastDouble = null;
246	        SimpleNode lastFunction = null;
247	        AtomicBoolean startSingle = new AtomicBoolean();
248	        AtomicBoolean startDouble = new AtomicBoolean();
249	        AtomicBoolean startFunction = new AtomicBoolean();
250	
251	        LiteralNode imageToken = null;
252	        for (SimpleToken token : tokens) {
253	            // break if eol
254	            if (token.getType().isEol()) {
255	                break;
256	            }
257	
258	            // create a node from the token
259	            SimpleNode node = createNode(token, startSingle, startDouble, startFunction);
260	            if (node != null) {
261	                // keep state of last single/double
262	                if (node instanceof SingleQuoteStart) {
263	                    lastSingle = node;
264	                } else if (node instanceof DoubleQuoteStart) {
265	                    lastDouble = node;
266	                } else if (node instanceof SimpleFunctionStart) {
267	                    lastFunction = node;
268	                }
269	
270	                // a new token was created so the current image token need to be added first
271	                if (imageToken != null) {
272	                    addImageToken(imageToken);
273	                    imageToken = null;
274	                }
275	                // and then add the created node
276	                nodes.add(node);
277	                // continue to next
278	                continue;
279	            }
280	
281	            // if no token was created then its a character/whitespace/escaped symbol
282	            // which we need to add together in the same image
283	            if (imageToken == null) {
284	                imageToken = new LiteralExpression(token);
285	            }
286	            imageToken.addText(token.getText());
287	        }
288	
289	        // append any leftover image tokens (when we reached eol)
290	        if (imageToken != null) {
291	            addImageToken(imageToken);
292	        }
293	
294	        // validate the single, double quote pairs and functions is in balance
295	        if (startSingle.get()) {
296	            int index = evalIndex(lastSingle);
297	            throw new SimpleParserException("single quote has no ending quote", index);
298	        }
299	        if (startDouble.get()) {
300	            int index = evalIndex(lastDouble);
301	            throw new SimpleParserException("double quote has no ending quote", index);
302	        }
303	        if (startFunction.get()) {
304	            // we have a start function, but no ending function
305	            int index = evalIndex(lastFunction);
306	            throw new SimpleParserException("function has no ending token", index);
307	        }
308	    }
309	
310	    private static int evalIndex(SimpleNode node) {
311	        return node != null ? node.getToken().getIndex() : 0;
312	    }
313	
314	    private void addImageToken(LiteralNode imageToken) {
315	        // this can be many things but lets check if this is numeric based, then we can optimize this
316	        String text = imageToken.getText();
317	
318	        // is this image from within a quoted block (single or double quoted)
319	        boolean quoted = false;
320	        if (!nodes.isEmpty()) {
321	            SimpleNode last = nodes.get(nodes.size() - 1);
322	            quoted = last instanceof SingleQuoteStart || last instanceof DoubleQuoteStart;
323	        }
324	
325	        boolean numeric = false;
326	        if (!quoted) {
327	            // if the text is not in a quoted block (literal text), then lets see if
328	            // its numeric then we can optimize this
329	            numeric = isNumber(text) || isFloatingNumber(text);
330	        }
331	        if (numeric) {
332	            nodes.add(new NumericExpression(imageToken.getToken(), text));
333	        } else {
334	            nodes.add(imageToken);
335	        }
336	    }
337	
338	    /**
339	     * Creates a node from the given token
340	     *
341	     * @param  token         the token
342	     * @param  startSingle   state of single quoted blocks
343	     * @param  startDouble   state of double quoted blocks
344	     * @param  startFunction state of function blocks
345	     * @return               the created node, or <tt>null</tt> to let a default node be created instead.
346	     */
347	    private SimpleNode createNode(
348	            SimpleToken token, AtomicBoolean startSingle, AtomicBoolean startDouble,
349	            AtomicBoolean startFunction) {
350	        if (token.getType().isFunctionStart()) {
351	            startFunction.set(true);
352	            return new SimpleFunctionStart(token, cacheExpression, skipFileFunctions);
353	        } else if (token.getType().isFunctionEnd()) {
354	            startFunction.set(false);
355	            return new SimpleFunctionEnd(token);
356	        }
357	
358	        // if we are inside a function, then we do not support any other kind of tokens
359	        // as we want all the tokens to be literal instead
360	        if (startFunction.get()) {
361	            return null;
362	        }
363	
364	        // okay so far we also want to support quotes
365	        if (token.getType().isSingleQuote()) {
366	            return createSingleQuoted(token, startSingle);
367	        } else if (token.getType().isDoubleQuote()) {
368	            return createDoubleQuoted(token, startDouble);
369	        }
370	
371	        // if we are inside a quote, then we do not support any further kind of tokens
372	        // as we want to only support embedded functions and all other kinds to be literal tokens
373	        if (startSingle.get() || startDouble.get()) {
374	            return null;
375	        }
376	
377	        // okay we are not inside a function or quote, so we want to support operators
378	        // and the special null/boolean value as well
379	        if (token.getType().isUnary()) {
380	            return new UnaryExpression(token);
381	        } else if (token.getType().isBinary()) {
382	            return new BinaryExpression(token);
383	        } else if (token.getType().isTernary()) {
384	            return new TernaryExpression(token);
385	        } else if (token.getType().isOther()) {
386	            return new OtherExpression(token);
387	        } else if (token.getType().isChain()) {
388	            return new ChainExpression(token);
389	        } else if (token.getType().isLogical()) {
390	            return new LogicalExpression(token);
391	        } else if (token.getType().isNullValue()) {
392	            return new NullExpression(token);
393	        } else if (token.getType().isBooleanValue()) {
394	            return new BooleanExpression(token);
395	        }
396	
397	        // by returning null, we will let the parser determine what to do
398	        return null;
399	    }
400	
401	    private static SimpleNode createDoubleQuoted(SimpleToken token, AtomicBoolean startDouble) {
402	        SimpleNode answer;
403	        boolean start = startDouble.get();
404	        if (!start) {
405	            answer = new DoubleQuoteStart(token);
406	        } else {
407	            answer = new DoubleQuoteEnd(token);
408	        }
409	        // flip state on start/end flag
410	        startDouble.set(!start);
411	        return answer;
412	    }
413	
414	    private static SimpleNode createSingleQuoted(SimpleToken token, AtomicBoolean startSingle) {
415	        SimpleNode answer;
416	        boolean start = startSingle.get();
417	        if (!start) {
418	            answer = new SingleQuoteStart(token);
419	        } else {
420	            answer = new SingleQuoteEnd(token);
421	        }
422	        // flip state on start/end flag
423	        startSingle.set(!start);
424	        return answer;
425	    }
426	
427	    /**
428	     * Removes any ignorable whitespace tokens.
429	     * <p/>
430	     * During the initial parsing (input -> tokens), then there may be excessive whitespace tokens, which can safely be
431	     * removed, which makes the succeeding parsing easier.
432	     */
433	    private void removeIgnorableWhiteSpaceTokens() {
434	        // remove all ignored
435	        tokens.removeIf(t -> t.getType().isIgnore());
436	
437	        // white space can be removed if its not part of a quoted text or within function(s)
438	        boolean quote = false;
439	        int functionCount = 0;
440	
441	        Iterator<SimpleToken> it = tokens.iterator();
442	        while (it.hasNext()) {
443	            SimpleToken token = it.next();
444	            if (token.getType().isSingleQuote()) {
445	                quote = !quote;
446	            } else if (!quote) {
447	                if (token.getType().isFunctionStart()) {
448	                    functionCount++;
449	                } else if (token.getType().isFunctionEnd()) {
450	                    functionCount--;
451	                } else if (token.getType().isWhitespace() && functionCount == 0) {
452	                    it.remove();
453	                }
454	            }
455	        }
456	    }
457	
458	    /**
459	     * Prepares binary expressions.
460	     * <p/>
461	     * This process prepares the binary expressions in the AST. This is done by linking the binary operator with both
462	     * the right and left hand side nodes, to have the AST graph updated and prepared properly.
463	     * <p/>
464	     * So when the AST node is later used to create the {@link Predicate}s to be used by Camel then the AST graph has a
465	     * linked and prepared graph of nodes which represent the input expression.
466	     */
467	    private void prepareBinaryExpressions(List<SimpleNode> nodes) {
468	        Deque<SimpleNode> stack = new ArrayDeque<>();
469	
470	        SimpleNode left = null;
471	        for (int i = 0; i < nodes.size(); i++) {
472	            if (left == null) {
473	                left = i > 0 ? nodes.get(i - 1) : null;
474	            }
475	            SimpleNode token = nodes.get(i);
476	            SimpleNode right = i < nodes.size() - 1 ? nodes.get(i + 1) : null;
477	
478	            if (token instanceof BinaryExpression binary) {
479	                // remember the binary operator
480	                String operator = binary.getOperator().toString();
481	
482	                if (left == null) {
483	                    throw new SimpleParserException(
484	                            "Binary operator " + operator + " has no left hand side token", token.getToken().getIndex());
485	                }
486	                if (!binary.acceptLeftNode(left)) {
487	                    throw new SimpleParserException(
488	                            "Binary operator " + operator + " does not support left hand side token " + left.getToken(),
489	                            token.getToken().getIndex());
490	                }
491	                if (right == null) {
492	                    throw new SimpleParserException(
493	                            "Binary operator " + operator + " has no right hand side token", token.getToken().getIndex());
494	                }
495	                if (!binary.acceptRightNode(right)) {
496	                    throw new SimpleParserException(
497	                            "Binary operator " + operator + " does not support right hand side token " + right.getToken(),
498	                            token.getToken().getIndex());
499	                }
500	
501	                // pop previous as we need to replace it with this binary operator
502	                stack.pop();
503	                stack.push(token);
504	                // advantage after the right hand side
505	                i++;
506	                // this token is now the left for the next loop
507	                left = token;
508	            } else {
509	                // clear left
510	                left = null;
511	                stack.push(token);
512	            }
513	        }
514	
515	        nodes.clear();
516	        nodes.addAll(stack);
517	        // must reverse as it was added from a stack that is reverse
518	        Collections.reverse(nodes);
519	    }
520	
521	    /**
522	     * Prepares logical expressions.
523	     * <p/>
524	     * This process prepares the logical expressions in the AST. This is done by linking the logical operator with both
525	     * the right and left hand side nodes, to have the AST graph updated and prepared properly.
526	     * <p/>
527	     * So when the AST node is later used to create the {@link Predicate}s to be used by Camel then the AST graph has a
528	     * linked and prepared graph of nodes which represent the input expression.
529	     */
530	    private void prepareLogicalExpressions(List<SimpleNode> nodes) {
531	        Deque<SimpleNode> stack = new ArrayDeque<>();
532	
533	        SimpleNode left = null;
534	        for (int i = 0; i < nodes.size(); i++) {
535	            if (left == null) {
536	                left = i > 0 ? nodes.get(i - 1) : null;
537	            }
538	            SimpleNode token = nodes.get(i);
539	            SimpleNode right = i < nodes.size() - 1 ? nodes.get(i + 1) : null;
540	
541	            if (token instanceof LogicalExpression logical) {
542	                // remember the logical operator
543	                String operator = logical.getOperator().toString();
544	
545	                if (left == null) {
546	                    throw new SimpleParserException(
547	                            "Logical operator " + operator + " has no left hand side token", token.getToken().getIndex());
548	                }
549	                if (!logical.acceptLeftNode(left)) {
550	                    throw new SimpleParserException(
551	                            "Logical operator " + operator + " does not support left hand side token " + left.getToken(),
552	                            token.getToken().getIndex());
553	                }
554	                if (right == null) {
555	                    throw new SimpleParserException(
556	                            "Logical operator " + operator + " has no right hand side token", token.getToken().getIndex());
557	                }
558	                if (!logical.acceptRightNode(right)) {
559	                    throw new SimpleParserException(
560	                            "Logical operator " + operator + " does not support right hand side token " + left.getToken(),
561	                            token.getToken().getIndex());
562	                }
563	
564	                // pop previous as we need to replace it with this binary operator
565	                stack.pop();
566	                stack.push(token);
567	                // advantage after the right hand side
568	                i++;
569	                // this token is now the left for the next loop
570	                left = token;
571	            } else {
572	                // clear left
573	                left = null;
574	                stack.push(token);
575	            }
576	        }
577	
578	        nodes.clear();
579	        nodes.addAll(stack);
580	        // must reverse as it was added from a stack that is reverse
581	        Collections.reverse(nodes);
582	    }
583	
584	    /**
585	     * Creates the {@link Predicate}s from the AST nodes.
586	     *
587	     * @return the created {@link Predicate}s, is never <tt>null</tt>.
588	     */
589	    private List<Predicate> createPredicates() {
590	        List<Predicate> answer = new ArrayList<>();
591	        for (SimpleNode node : nodes) {
592	            Expression exp = node.createExpression(camelContext, expression);
593	            if (exp != null) {
594	                Predicate predicate = ExpressionToPredicateAdapter.toPredicate(exp);
595	                answer.add(predicate);
596	            }
597	        }
598	        return answer;
599	    }
600	
601	    // --------------------------------------------------------------
602	    // grammar
603	    // --------------------------------------------------------------
604	
605	    // the predicate parser understands a lot more than the expression parser
606	    // - boolean value = either true or false value (literal)
607	    // - single quoted = block of nodes enclosed by single quotes
608	    // - double quoted = block of nodes enclosed by double quotes
609	    // - single quoted with functions = block of nodes enclosed by single quotes allowing embedded functions
610	    // - double quoted with functions = block of nodes enclosed by double quotes allowing embedded functions
611	    // - function = simple functions such as ${body} etc
612	    // - numeric = numeric value
613	    // - boolean = boolean value
614	    // - null = null value
615	    // - unary operator = operator attached to the left hand side node
616	    // - binary operator = operator attached to both the left and right hand side nodes
617	    // - other operator = operator attached to both the left and right hand side nodes
618	    // - logical operator = operator attached to both the left and right hand side nodes
619	
620	    protected boolean isBooleanValue() {
621	        if (accept(TokenType.booleanValue)) {
622	            return true;
623	        }
624	        return false;
625	    }
626	
627	    protected boolean singleQuotedLiteralWithFunctionsText() {
628	        if (accept(TokenType.singleQuote)) {
629	            nextToken(TokenType.singleQuote, TokenType.eol, TokenType.functionStart, TokenType.functionEnd);
630	            while (!token.getType().isSingleQuote() && !token.getType().isEol()) {
631	                // we need to loop until we find the ending single quote, or the eol
632	                nextToken(TokenType.singleQuote, TokenType.eol, TokenType.functionStart, TokenType.functionEnd);
633	            }
634	            expect(TokenType.singleQuote);
635	            return true;
636	        }
637	        return false;
638	    }
639	
640	    protected boolean singleQuotedLiteralText() {
641	        if (accept(TokenType.singleQuote)) {
642	            nextToken(TokenType.singleQuote, TokenType.eol);
643	            while (!token.getType().isSingleQuote() && !token.getType().isEol()) {
644	                // we need to loop until we find the ending single quote, or the eol
645	                nextToken(TokenType.singleQuote, TokenType.eol);
646	            }
647	            expect(TokenType.singleQuote);
648	            return true;
649	        }
650	        return false;
651	    }
652	
653	    protected boolean doubleQuotedLiteralWithFunctionsText() {
654	        if (accept(TokenType.doubleQuote)) {
655	            nextToken(TokenType.doubleQuote, TokenType.eol, TokenType.functionStart, TokenType.functionEnd);
656	            while (!token.getType().isDoubleQuote() && !token.getType().isEol()) {
657	                // we need to loop until we find the ending double quote, or the eol
658	                nextToken(TokenType.doubleQuote, TokenType.eol, TokenType.functionStart, TokenType.functionEnd);
659	            }
660	            expect(TokenType.doubleQuote);
661	            return true;
662	        }
663	        return false;
664	    }
665	
666	    protected boolean doubleQuotedLiteralText() {
667	        if (accept(TokenType.doubleQuote)) {
668	            nextToken(TokenType.doubleQuote, TokenType.eol);
669	            while (!token.getType().isDoubleQuote() && !token.getType().isEol()) {
670	                // we need to loop until we find the ending double quote, or the eol
671	                nextToken(TokenType.doubleQuote, TokenType.eol);
672	            }
673	            expect(TokenType.doubleQuote);
674	            return true;
675	        }
676	        return false;
677	    }
678	
679	    protected boolean functionText() {
680	        if (accept(TokenType.functionStart)) {
681	            nextToken();
682	            while (!token.getType().isFunctionEnd() && !token.getType().isEol()) {
683	                if (token.getType().isFunctionStart()) {
684	                    // embedded function
685	                    functionText();
686	                }
687	                // we need to loop until we find the ending function quote, an embedded function, or the eol
688	                nextToken();
689	            }
690	            // if its not an embedded function then we expect the end token
691	            if (!token.getType().isFunctionStart()) {
692	                expect(TokenType.functionEnd);
693	            }
694	            return true;
695	        }
696	        return false;
697	    }
698	
699	    protected boolean unaryOperator() {
700	        if (accept(TokenType.unaryOperator)) {
701	            nextToken();
702	            // there should be a whitespace after the operator
703	            expect(TokenType.whiteSpace);
704	            return true;
705	        }
706	        return false;
707	    }
708	
709	    protected boolean binaryOperator() {
710	        if (accept(TokenType.binaryOperator)) {
711	            // remember the binary operator
712	            BinaryOperatorType operatorType = BinaryOperatorType.asOperator(token.getText());
713	
714	            nextToken();
715	            // there should be at least one whitespace after the operator
716	            expectAndAcceptMore(TokenType.whiteSpace);
717	
718	            // okay a binary operator may not support all kind if preceding parameters, so we need to limit this
719	            BinaryOperatorType.ParameterType[] types = BinaryOperatorType.supportedParameterTypes(operatorType);
720	
721	            // based on the parameter types the binary operator support, we need to set this state into
722	            // the following booleans so we know how to proceed in the grammar
723	            boolean literalWithFunctionsSupported;
724	            boolean literalSupported;
725	            boolean functionSupported;
726	            boolean numericSupported;
727	            boolean booleanSupported;
728	            boolean nullSupported;
729	            boolean minusSupported;
730	            if (types == null || types.length == 0) {
731	                literalWithFunctionsSupported = true;
732	                // favor literal with functions over literals without functions
733	                literalSupported = false;
734	                functionSupported = true;
735	                numericSupported = true;
736	                booleanSupported = true;
737	                nullSupported = true;
738	                minusSupported = true;
739	            } else {
740	                literalWithFunctionsSupported = false;
741	                literalSupported = false;
742	                functionSupported = false;
743	                numericSupported = false;
744	                booleanSupported = false;
745	                nullSupported = false;
746	                minusSupported = false;
747	                for (BinaryOperatorType.ParameterType parameterType : types) {
748	                    literalSupported |= parameterType.isLiteralSupported();
749	                    literalWithFunctionsSupported |= parameterType.isLiteralWithFunctionSupport();
750	                    functionSupported |= parameterType.isFunctionSupport();
751	                    nullSupported |= parameterType.isNumericValueSupported();
752	                    booleanSupported |= parameterType.isBooleanValueSupported();
753	                    nullSupported |= parameterType.isNullValueSupported();
754	                    minusSupported |= parameterType.isMinusValueSupported();
755	                }
756	            }
757	
758	            // then we proceed in the grammar according to the parameter types supported by the given binary operator
759	            if ((literalWithFunctionsSupported && singleQuotedLiteralWithFunctionsText())
760	                    || (literalWithFunctionsSupported && doubleQuotedLiteralWithFunctionsText())
761	                    || (literalSupported && singleQuotedLiteralText())
762	                    || (literalSupported && doubleQuotedLiteralText())
763	                    || (functionSupported && functionText())
764	                    || (numericSupported && numericValue())
765	                    || (booleanSupported && booleanValue())
766	                    || (nullSupported && nullValue())
767	                    || (minusSupported && minusValue())) {
768	                // then after the right hand side value, there should be a whitespace if there is more tokens
769	                nextToken();
770	                if (!token.getType().isEol()) {
771	                    expect(TokenType.whiteSpace);
772	                }
773	            } else {
774	                throw new SimpleParserException(
775	                        "Binary operator " + operatorType + " does not support token " + token, token.getIndex());
776	            }
777	            return true;
778	        }
779	        return false;
780	    }
781	
782	    protected boolean ternaryOperator() {
783	        if (accept(TokenType.ternaryOperator)) {
784	            nextToken();
785	            // there should be at least one whitespace after the operator
786	            expectAndAcceptMore(TokenType.whiteSpace);
787	
788	            // then we expect either some quoted text, another function, or a numeric, boolean or null value
789	            if (singleQuotedLiteralWithFunctionsText()
790	                    || doubleQuotedLiteralWithFunctionsText()
791	                    || functionText()
792	                    || numericValue()
793	                    || booleanValue()
794	                    || nullValue()) {
795	                // then after the right hand side value, there should be a whitespace if there is more tokens
796	                nextToken();
797	                if (!token.getType().isEol()) {
798	                    expect(TokenType.whiteSpace);
799	                }
800	            } else {
801	                throw new SimpleParserException(
802	                        "Ternary operator does not support token " + token, token.getIndex());
803	            }
804	            return true;
805	        }
806	        return false;
807	    }
808	
809	    protected boolean otherOperator() {
810	        if (accept(TokenType.otherOperator)) {
811	            // remember the other operator
812	            OtherOperatorType operatorType = OtherOperatorType.asOperator(token.getText());
813	
814	            nextToken();
815	            // there should be at least one whitespace after the operator
816	            expectAndAcceptMore(TokenType.whiteSpace);
817	
818	            // then we expect either some quoted text, another function, or a numeric, boolean or null value
819	            if (singleQuotedLiteralWithFunctionsText()
820	                    || doubleQuotedLiteralWithFunctionsText()
821	                    || functionText()
822	                    || numericValue()
823	                    || booleanValue()
824	                    || nullValue()) {
825	                // then after the right hand side value, there should be a whitespace if there is more tokens
826	                nextToken();
827	                if (!token.getType().isEol()) {
828	                    expect(TokenType.whiteSpace);
829	                }
830	            } else {
831	                throw new SimpleParserException(
832	                        "Other operator " + operatorType + " does not support token " + token, token.getIndex());
833	            }
834	            return true;
835	        }
836	        return false;
837	    }
838	
839	    protected boolean chainOperator() {
840	        if (accept(TokenType.chainOperator)) {
841	            // remember the chain operator
842	            ChainOperatorType operatorType = ChainOperatorType.asOperator(token.getText());
843	
844	            nextToken();
845	            // there should be at least one whitespace after the operator
846	            expectAndAcceptMore(TokenType.whiteSpace);
847	
848	            // then we expect either some quoted text, another function, or a numeric, boolean or null value
849	            if (singleQuotedLiteralWithFunctionsText()
850	                    || doubleQuotedLiteralWithFunctionsText()
851	                    || functionText()
852	                    || numericValue()
853	                    || booleanValue()
854	                    || nullValue()) {
855	                // then after the right hand side value, there should be a whitespace if there is more tokens
856	                nextToken();
857	                if (!token.getType().isEol()) {
858	                    expectAndAcceptMore(TokenType.whiteSpace);
859	                }
860	            } else {
861	                throw new SimpleParserException(
862	                        "Chain operator " + operatorType + " does not support token " + token, token.getIndex());
863	            }
864	            return true;
865	        }
866	        return false;
867	    }
868	
869	    protected boolean logicalOperator() {
870	        if (accept(TokenType.logicalOperator)) {
871	            // remember the logical operator
872	            LogicalOperatorType operatorType = LogicalOperatorType.asOperator(token.getText());
873	
874	            nextToken();
875	            // there should be at least one whitespace after the operator
876	            expectAndAcceptMore(TokenType.whiteSpace);
877	
878	            // then we expect either some quoted text, another function, or a numeric, boolean or null value
879	            if (singleQuotedLiteralWithFunctionsText()
880	                    || doubleQuotedLiteralWithFunctionsText()
881	                    || functionText()
882	                    || numericValue()
883	                    || booleanValue()
884	                    || nullValue()) {
885	                // then after the right hand side value, there should be a whitespace if there is more tokens
886	                nextToken();
887	                if (!token.getType().isEol()) {
888	                    expect(TokenType.whiteSpace);
889	                }
890	            } else {
891	                throw new SimpleParserException(
892	                        "Logical operator " + operatorType + " does not support token " + token, token.getIndex());
893	            }
894	            return true;
895	        }
896	        return false;
897	    }
898	
899	    protected boolean numericValue() {
900	        return accept(TokenType.numericValue);
901	        // no other tokens to check so do not use nextToken
902	    }
903	
904	    protected boolean booleanValue() {
905	        return accept(TokenType.booleanValue);
906	        // no other tokens to check so do not use nextToken
907	    }
908	
909	    protected boolean nullValue() {
910	        return accept(TokenType.nullValue);
911	        // no other tokens to check so do not use nextToken
912	    }
913	
914	    protected boolean minusValue() {
915	        nextToken();
916	        return accept(TokenType.numericValue);
917	        // no other tokens to check so do not use nextToken
918	    }
919	
920	}
