40	/**
41	 * Represents a binary expression in the AST.
42	 */
43	public class BinaryExpression extends BaseSimpleNode {
44	
45	    // this is special for the range operator where you define the range as from..to (where from and to are numbers)
46	    private static final Pattern RANGE_PATTERN = Pattern.compile("^(\\d+)(\\.\\.)(\\d+)$");
47	
48	    private final BinaryOperatorType operator;
49	    private SimpleNode left;
50	    private SimpleNode right;
51	
52	    public BinaryExpression(SimpleToken token) {
53	        super(token);
54	        operator = BinaryOperatorType.asOperator(token.getText());
55	    }
56	
57	    @Override
58	    public String toString() {
59	        return left + " " + token.getText() + " " + right;
60	    }
61	
62	    public boolean acceptLeftNode(SimpleNode lef) {
63	        this.left = lef;
64	        return true;
65	    }
66	
67	    public boolean acceptRightNode(SimpleNode right) {
68	        this.right = right;
69	        return true;
70	    }
71	
72	    public BinaryOperatorType getOperator() {
73	        return operator;
74	    }
75	
76	    public SimpleNode getLeft() {
77	        return left;
78	    }
79	
80	    public SimpleNode getRight() {
81	        return right;
82	    }
83	
84	    @Override
85	    public Expression createExpression(CamelContext camelContext, String expression) {
86	        org.apache.camel.util.ObjectHelper.notNull(left, "left node", this);
87	        org.apache.camel.util.ObjectHelper.notNull(right, "right node", this);
88	
89	        final Expression leftExp = left.createExpression(camelContext, expression);
90	        final Expression rightExp = right.createExpression(camelContext, expression);
91	
92	        if (operator == BinaryOperatorType.EQ) {
93	            return createExpression(camelContext, leftExp, rightExp, PredicateBuilder.isEqualTo(leftExp, rightExp));
94	        } else if (operator == BinaryOperatorType.EQ_IGNORE) {
95	            return createExpression(camelContext, leftExp, rightExp, PredicateBuilder.isEqualToIgnoreCase(leftExp, rightExp));
96	        } else if (operator == BinaryOperatorType.GT) {
97	            return createExpression(camelContext, leftExp, rightExp, PredicateBuilder.isGreaterThan(leftExp, rightExp));
98	        } else if (operator == BinaryOperatorType.GTE) {
99	            return createExpression(camelContext, leftExp, rightExp,
100	                    PredicateBuilder.isGreaterThanOrEqualTo(leftExp, rightExp));
101	        } else if (operator == BinaryOperatorType.LT) {
102	            return createExpression(camelContext, leftExp, rightExp, PredicateBuilder.isLessThan(leftExp, rightExp));
103	        } else if (operator == BinaryOperatorType.LTE) {
104	            return createExpression(camelContext, leftExp, rightExp, PredicateBuilder.isLessThanOrEqualTo(leftExp, rightExp));
105	        } else if (operator == BinaryOperatorType.NOT_EQ) {
106	            return createExpression(camelContext, leftExp, rightExp, PredicateBuilder.isNotEqualTo(leftExp, rightExp));
107	        } else if (operator == BinaryOperatorType.NOT_EQ_IGNORE) {
108	            return createExpression(camelContext, leftExp, rightExp,
109	                    PredicateBuilder.not(PredicateBuilder.isEqualToIgnoreCase(leftExp, rightExp)));
110	        } else if (operator == BinaryOperatorType.CONTAINS) {
111	            return createExpression(camelContext, leftExp, rightExp, PredicateBuilder.contains(leftExp, rightExp));
112	        } else if (operator == BinaryOperatorType.NOT_CONTAINS) {
113	            return createExpression(camelContext, leftExp, rightExp,
114	                    PredicateBuilder.not(PredicateBuilder.contains(leftExp, rightExp)));
115	        } else if (operator == BinaryOperatorType.CONTAINS_IGNORECASE) {
116	            return createExpression(camelContext, leftExp, rightExp, PredicateBuilder.containsIgnoreCase(leftExp, rightExp));
117	        } else if (operator == BinaryOperatorType.NOT_CONTAINS_IGNORECASE) {
118	            return createExpression(camelContext, leftExp, rightExp,
119	                    PredicateBuilder.not(PredicateBuilder.containsIgnoreCase(leftExp, rightExp)));
120	        } else if (operator == BinaryOperatorType.IS || operator == BinaryOperatorType.NOT_IS) {
121	            return createIsExpression(camelContext, expression, leftExp, rightExp);
122	        } else if (operator == BinaryOperatorType.REGEX || operator == BinaryOperatorType.NOT_REGEX) {
123	            return createRegexExpression(camelContext, leftExp, rightExp);
124	        } else if (operator == BinaryOperatorType.IN || operator == BinaryOperatorType.NOT_IN) {
125	            return createInExpression(camelContext, leftExp, rightExp);
126	        } else if (operator == BinaryOperatorType.RANGE || operator == BinaryOperatorType.NOT_RANGE) {
127	            return createRangeExpression(camelContext, expression, leftExp, rightExp);
128	        } else if (operator == BinaryOperatorType.STARTS_WITH) {
129	            return createExpression(camelContext, leftExp, rightExp, PredicateBuilder.startsWith(leftExp, rightExp));
130	        } else if (operator == BinaryOperatorType.NOT_STARTS_WITH) {
131	            return createExpression(camelContext, leftExp, rightExp,
132	                    PredicateBuilder.not(PredicateBuilder.startsWith(leftExp, rightExp)));
133	        } else if (operator == BinaryOperatorType.ENDS_WITH) {
134	            return createExpression(camelContext, leftExp, rightExp, PredicateBuilder.endsWith(leftExp, rightExp));
135	        } else if (operator == BinaryOperatorType.NOT_ENDS_WITH) {
136	            return createExpression(camelContext, leftExp, rightExp,
137	                    PredicateBuilder.not(PredicateBuilder.endsWith(leftExp, rightExp)));
138	        }
139	
140	        throw new SimpleParserException("Unknown binary operator " + operator, token.getIndex());
141	    }
142	
143	    private Expression createIsExpression(
144	            final CamelContext camelContext, final String expression, final Expression leftExp, final Expression rightExp) {
145	        return new Expression() {
146	            @Override
147	            public <T> T evaluate(Exchange exchange, Class<T> type) {
148	
149	                String name = rightExp.evaluate(exchange, String.class);
150	                if (name == null || "null".equals(name)) {
151	                    throwMissingClass();
152	                }
153	                Class<?> rightType = camelContext.getClassResolver().resolveClass(name);
154	                if (rightType == null) {
155	                    throwClassNotFound(name);
156	                }
157	
158	                Predicate predicate = PredicateBuilder.isInstanceOf(leftExp, rightType);
159	                if (operator == BinaryOperatorType.NOT_IS) {
160	                    predicate = PredicateBuilder.not(predicate);
161	                }
162	                boolean answer = predicate.matches(exchange);
163	
164	                return camelContext.getTypeConverter().convertTo(type, answer);
165	            }
166	
167	            private void throwClassNotFound(String name) {
168	                throw new SimpleIllegalSyntaxException(
169	                        expression, right.getToken().getIndex(),
170	                        operator + " operator cannot find class with name: " + name);
171	            }
172	
173	            private void throwMissingClass() {
174	                throw new SimpleIllegalSyntaxException(
175	                        expression, right.getToken().getIndex(),
176	                        operator + " operator cannot accept null. A class type must be provided.");
177	            }
178	
179	            @Override
180	            public String toString() {
181	                return left + " " + token.getText() + " " + right;
182	            }
183	        };
184	    }
185	
186	    private Expression createRegexExpression(
187	            final CamelContext camelContext, final Expression leftExp, final Expression rightExp) {
188	        return new Expression() {
189	            @Override
190	            public <T> T evaluate(Exchange exchange, Class<T> type) {
191	                // reg ex should use String pattern, so we evaluate the right hand side as a String
192	                Predicate predicate = PredicateBuilder.regex(leftExp, rightExp.evaluate(exchange, String.class));
193	                if (operator == BinaryOperatorType.NOT_REGEX) {
194	                    predicate = PredicateBuilder.not(predicate);
195	                }
196	                boolean answer = predicate.matches(exchange);
197	                return camelContext.getTypeConverter().convertTo(type, answer);
198	            }
199	
200	            @Override
201	            public String toString() {
202	                return left + " " + token.getText() + " " + right;
203	            }
204	        };
205	    }
206	
207	    private Expression createInExpression(
208	            final CamelContext camelContext, final Expression leftExp, final Expression rightExp) {
209	        return new Expression() {
210	            @Override
211	            public <T> T evaluate(Exchange exchange, Class<T> type) {
212	                // okay the in operator is a bit more complex as we need to build a list of values
213	                // from the right hand side expression.
214	                // each element on the right hand side must be separated by comma (default for create iterator)
215	                Iterator<?> it = ObjectHelper.createIterator(rightExp.evaluate(exchange, Object.class));
216	                List<Object> values = new ArrayList<>();
217	                while (it.hasNext()) {
218	                    values.add(it.next());
219	                }
220	                // then reuse value builder to create the in predicate with the list of values
221	                ValueBuilder vb = new ValueBuilder(leftExp);
222	                Predicate predicate = vb.in(values.toArray());
223	                if (operator == BinaryOperatorType.NOT_IN) {
224	                    predicate = PredicateBuilder.not(predicate);
225	                }
226	                boolean answer = predicate.matches(exchange);
227	                return camelContext.getTypeConverter().convertTo(type, answer);
228	            }
229	
230	            @Override
231	            public String toString() {
232	                return left + " " + token.getText() + " " + right;
233	            }
234	        };
235	    }
236	
237	    private Expression createRangeExpression(
238	            final CamelContext camelContext, final String expression, final Expression leftExp, final Expression rightExp) {
239	        return new Expression() {
240	            @Override
241	            public <T> T evaluate(Exchange exchange, Class<T> type) {
242	                Predicate predicate;
243	
244	                String range = rightExp.evaluate(exchange, String.class);
245	                Matcher matcher = RANGE_PATTERN.matcher(range);
246	                if (matcher.matches()) {
247	                    // wrap as constant expression for the from and to values
248	                    Expression from = ExpressionBuilder.constantExpression(matcher.group(1));
249	                    Expression to = ExpressionBuilder.constantExpression(matcher.group(3));
250	
251	                    // build a compound predicate for the range
252	                    predicate = PredicateBuilder.isGreaterThanOrEqualTo(leftExp, from);
253	                    predicate = PredicateBuilder.and(predicate, PredicateBuilder.isLessThanOrEqualTo(leftExp, to));
254	                } else {
255	                    throw new SimpleIllegalSyntaxException(
256	                            expression, right.getToken().getIndex(),
257	                            operator + " operator is not valid. Valid syntax:'from..to' (where from and to are numbers).");
258	                }
259	                if (operator == BinaryOperatorType.NOT_RANGE) {
260	                    predicate = PredicateBuilder.not(predicate);
261	                }
262	
263	                boolean answer = predicate.matches(exchange);
264	                return camelContext.getTypeConverter().convertTo(type, answer);
265	            }
266	
267	            @Override
268	            public String toString() {
269	                return left + " " + token.getText() + " " + right;
270	            }
271	        };
272	    }
273	
274	    private Expression createExpression(
275	            final CamelContext camelContext, final Expression left, final Expression right, final Predicate predicate) {
276	        return new Expression() {
277	            @Override
278	            public <T> T evaluate(Exchange exchange, Class<T> type) {
279	                boolean answer = predicate.matches(exchange);
280	                return camelContext.getTypeConverter().convertTo(type, answer);
281	            }
282	
283	            @Override
284	            public String toString() {
285	                return left + " " + token.getText() + " " + right;
286	            }
287	        };
288	    }
289	
290	    @Override
291	    public String createCode(CamelContext camelContext, String expression) throws SimpleParserException {
292	        return BaseSimpleParser.CODE_START + doCreateCode(camelContext, expression) + BaseSimpleParser.CODE_END;
293	    }
294	
295	    private String doCreateCode(CamelContext camelContext, String expression) throws SimpleParserException {
296	        org.apache.camel.util.ObjectHelper.notNull(left, "left node", this);
297	        org.apache.camel.util.ObjectHelper.notNull(right, "right node", this);
298	
299	        final String leftExp = left.createCode(camelContext, expression);
300	        final String rightExp = right.createCode(camelContext, expression);
301	
302	        if (operator == BinaryOperatorType.EQ) {
303	            return "isEqualTo(exchange, " + leftExp + ", " + rightExp + ")";
304	        } else if (operator == BinaryOperatorType.EQ_IGNORE) {
305	            return "isEqualToIgnoreCase(exchange, " + leftExp + ", " + rightExp + ")";
306	        } else if (operator == BinaryOperatorType.GT) {
307	            return "isGreaterThan(exchange, " + leftExp + ", " + rightExp + ")";
308	        } else if (operator == BinaryOperatorType.GTE) {
309	            return "isGreaterThanOrEqualTo(exchange, " + leftExp + ", " + rightExp + ")";
310	        } else if (operator == BinaryOperatorType.LT) {
311	            return "isLessThan(exchange, " + leftExp + ", " + rightExp + ")";
312	        } else if (operator == BinaryOperatorType.LTE) {
313	            return "isLessThanOrEqualTo(exchange, " + leftExp + ", " + rightExp + ")";
314	        } else if (operator == BinaryOperatorType.NOT_EQ) {
315	            return "isNotEqualTo(exchange, " + leftExp + ", " + rightExp + ")";
316	        } else if (operator == BinaryOperatorType.NOT_EQ_IGNORE) {
317	            return "!isEqualToIgnoreCase(exchange, " + leftExp + ", " + rightExp + ")";
318	        } else if (operator == BinaryOperatorType.CONTAINS) {
319	            return "contains(exchange, " + leftExp + ", " + rightExp + ")";
320	        } else if (operator == BinaryOperatorType.CONTAINS_IGNORECASE) {
321	            return "containsIgnoreCase(exchange, " + leftExp + ", " + rightExp + ")";
322	        } else if (operator == BinaryOperatorType.NOT_CONTAINS) {
323	            return "!contains(exchange, " + leftExp + ", " + rightExp + ")";
324	        } else if (operator == BinaryOperatorType.NOT_CONTAINS_IGNORECASE) {
325	            return "!containsIgnoreCase(exchange, " + leftExp + ", " + rightExp + ")";
326	        } else if (operator == BinaryOperatorType.IS) {
327	            String type = StringHelper.removeQuotes(rightExp);
328	            if (!type.endsWith(".class")) {
329	                type = type + ".class";
330	            }
331	            type = type.replace('$', '.');
332	            type = type.trim();
333	            return "is(exchange, " + leftExp + ", " + type + ")";
334	        } else if (operator == BinaryOperatorType.NOT_IS) {
335	            String type = StringHelper.removeQuotes(rightExp);
336	            if (!type.endsWith(".class")) {
337	                type = type + ".class";
338	            }
339	            type = type.replace('$', '.');
340	            type = type.trim();
341	            return "!is(exchange, " + leftExp + ", " + type + ")";
342	        } else if (operator == BinaryOperatorType.REGEX) {
343	            // regexp is a pain with escapes
344	            String escaped = rightExp.replace("\\", "\\\\");
345	            return "regexp(exchange, " + leftExp + ", " + escaped + ")";
346	        } else if (operator == BinaryOperatorType.NOT_REGEX) {
347	            // regexp is a pain with escapes
348	            String escaped = rightExp.replace("\\", "\\\\");
349	            return "!regexp(exchange, " + leftExp + ", " + escaped + ")";
350	        } else if (operator == BinaryOperatorType.IN) {
351	            return "in(exchange, " + leftExp + ", " + rightExp + ")";
352	        } else if (operator == BinaryOperatorType.NOT_IN) {
353	            return "!in(exchange, " + leftExp + ", " + rightExp + ")";
354	        } else if (operator == BinaryOperatorType.RANGE) {
355	            return "range(exchange, " + leftExp + ", " + rightExp + ")";
356	        } else if (operator == BinaryOperatorType.NOT_RANGE) {
357	            return "!range(exchange, " + leftExp + ", " + rightExp + ")";
358	        } else if (operator == BinaryOperatorType.STARTS_WITH) {
359	            return "startsWith(exchange, " + leftExp + ", " + rightExp + ")";
360	        } else if (operator == BinaryOperatorType.NOT_STARTS_WITH) {
361	            return "!startsWith(exchange, " + leftExp + ", " + rightExp + ")";
362	        } else if (operator == BinaryOperatorType.ENDS_WITH) {
363	            return "endsWith(exchange, " + leftExp + ", " + rightExp + ")";
364	        } else if (operator == BinaryOperatorType.NOT_ENDS_WITH) {
365	            return "!endsWith(exchange, " + leftExp + ", " + rightExp + ")";
366	        }
367	
368	        throw new SimpleParserException("Unknown binary operator " + operator, token.getIndex());
369	    }
370	
371	}
