81	
82	    /**
83	     * Advances the parser position to the next known {@link SimpleToken} in the input.
84	     */
85	    protected void nextToken() {
86	        if (index < expression.length()) {
87	            SimpleToken next = tokenizer.nextToken(expression, index, allowEscape);
88	            // add token
89	            tokens.add(next);
90	            token = next;
91	            // position index after the token
92	            previousIndex = index;
93	            index += next.getLength();
94	        } else {
95	            // end of tokens
96	            token = new SimpleToken(new SimpleTokenType(TokenType.eol, null), index);
97	        }
98	    }
99	
100	    protected void skipToken() {
101	        if (index < expression.length()) {
102	            SimpleToken next = tokenizer.nextToken(expression, index, allowEscape);
103	            token = next;
104	            // position index after the token
105	            previousIndex = index;
106	            index += next.getLength();
107	        } else {
108	            // end of tokens
109	            token = new SimpleToken(new SimpleTokenType(TokenType.eol, null), index);
110	        }
111	    }
112	
113	    /**
114	     * Advances the parser position to the next known {@link SimpleToken} in the input.
115	     *
116	     * @param filter filter for accepted token types
117	     */
118	    protected void nextToken(TokenType... filter) {
119	        if (index < expression.length()) {
120	            SimpleToken next = tokenizer.nextToken(expression, index, allowEscape, filter);
121	            // add token
122	            tokens.add(next);
123	            token = next;
124	            // position index after the token
125	            previousIndex = index;
126	            index += next.getLength();
127	        } else {
128	            // end of tokens
129	            token = new SimpleToken(new SimpleTokenType(TokenType.eol, null), index);
130	        }
131	    }
132	
133	    /**
134	     * Clears the parser state, which means it can be used for parsing a new input.
135	     */
136	    protected void clear() {
137	        token = null;
138	        previousIndex = 0;
139	        index = 0;
140	        tokens.clear();
141	        nodes.clear();
142	    }
143	
144	    /**
145	     * Prepares blocks, such as functions, single or double-quoted texts.
146	     * <p/>
147	     * This process prepares the {@link Block}s in the AST. This is done by linking child {@link SimpleNode nodes} which
148	     * are within the start and end of the blocks, as child to the given block. This is done to have the AST graph
149	     * updated and prepared properly.
150	     * <p/>
151	     * So when the AST node is later used to create the {@link org.apache.camel.Predicate}s or
152	     * {@link org.apache.camel.Expression}s to be used by Camel then the AST graph has a linked and prepared graph of
153	     * nodes which represent the input expression.
154	     */
155	    protected void prepareBlocks(List<SimpleNode> nodes) {
156	        List<SimpleNode> answer = new ArrayList<>();
157	        Deque<Block> stack = new ArrayDeque<>();
158	
159	        for (SimpleNode token : nodes) {
160	            if (token instanceof BlockStart blockStart) {
161	                // a new block is started, so push on the stack
162	                stack.push(blockStart);
163	            } else if (token instanceof BlockEnd) {
164	                // end block is just an abstract mode, so we should not add it
165	                if (stack.isEmpty()) {
166	                    throw new SimpleParserException(
167	                            token.getToken().getType().getType() + " has no matching start token", token.getToken().getIndex());
168	                }
169	
170	                Block top = stack.pop();
171	                // if there is a block on the stack then it should accept the child token
172	                acceptOrAdd(answer, stack, top);
173	            } else {
174	                // if there is a block on the stack then it should accept the child token
175	                acceptOrAdd(answer, stack, token);
176	            }
177	        }
178	
179	        // replace nodes from the stack
180	        nodes.clear();
181	        nodes.addAll(answer);
182	    }
183	
184	    private static void acceptOrAdd(List<SimpleNode> answer, Deque<Block> stack, SimpleNode token) {
185	        Block block = stack.isEmpty() ? null : stack.peek();
186	        if (block != null) {
187	            if (!block.acceptAndAddNode(token)) {
188	                throw new SimpleParserException(
189	                        block.getToken().getType() + " cannot accept " + token.getToken().getType(),
190	                        token.getToken().getIndex());
191	            }
192	        } else {
193	            // no block, so add to answer
194	            answer.add(token);
195	        }
196	    }
197	
198	    /**
199	     * Prepares unary expressions.
200	     * <p/>
201	     * This process prepares the unary expressions in the AST. This is done by linking the unary operator with the left
202	     * hand side node, to have the AST graph updated and prepared properly.
203	     * <p/>
204	     * So when the AST node is later used to create the {@link org.apache.camel.Predicate}s or
205	     * {@link org.apache.camel.Expression}s to be used by Camel then the AST graph has a linked and prepared graph of
206	     * nodes which represent the input expression.
207	     */
208	    protected void prepareUnaryExpressions(List<SimpleNode> nodes) {
209	        Deque<SimpleNode> stack = new ArrayDeque<>();
210	
211	        for (SimpleNode node : nodes) {
212	            if (node instanceof UnaryExpression token) {
213	                // remember the logical operator
214	                String operator = token.getOperator().toString();
215	
216	                SimpleNode previous = stack.isEmpty() ? null : stack.pop();
217	                if (previous == null) {
218	                    throw new SimpleParserException(
219	                            "Unary operator " + operator + " has no left hand side token", token.getToken().getIndex());
220	                } else {
221	                    token.acceptLeft(previous);
222	                }
223	            }
224	            stack.push(node);
225	        }
226	
227	        // replace nodes from the stack
228	        nodes.clear();
229	        nodes.addAll(stack);
230	        // must reverse as it was added from a stack that is reverse
231	        Collections.reverse(nodes);
232	    }
233	
234	    /**
235	     * Prepares chain expressions.
236	     * <p/>
237	     * This process prepares the other expressions in the AST. This is done by linking the other operator with both the
238	     * right and left hand side nodes, to have the AST graph updated and prepared properly.
239	     * <p/>
240	     * So when the AST node is later used to create the {@link Predicate}s to be used by Camel then the AST graph has a
241	     * linked and prepared graph of nodes which represent the input expression.
242	     */
243	    protected void prepareChainExpression(List<SimpleNode> nodes) {
244	        Deque<SimpleNode> stack = new ArrayDeque<>();
245	
246	        SimpleNode left = null;
247	        for (int i = 0; i < nodes.size(); i++) {
248	            if (left == null) {
249	                left = i > 0 ? nodes.get(i - 1) : null;
250	            }
251	            SimpleNode token = nodes.get(i);
252	            SimpleNode right = i < nodes.size() - 1 ? nodes.get(i + 1) : null;
253	
254	            if (token instanceof ChainExpression chain) {
255	                // remember the chain operator
256	                String operator = chain.getOperator().toString();
257	
258	                if (left == null) {
259	                    throw new SimpleParserException(
260	                            "Chain operator " + operator + " has no left hand side token", token.getToken().getIndex());
261	                }
262	                if (right == null) {
263	                    throw new SimpleParserException(
264	                            "Chain operator " + operator + " has no right hand side token", token.getToken().getIndex());
265	                }
266	
267	                if (left instanceof ChainExpression chainLeft) {
268	                    // append to existing chain on right hand side
269	                    chainLeft.acceptRightNode(right);
270	                } else {
271	                    if (!chain.acceptLeftNode(left)) {
272	                        throw new SimpleParserException(
273	                                "Chain operator " + operator + " does not support left hand side token " + left.getToken(),
274	                                token.getToken().getIndex());
275	                    }
276	                    if (!chain.acceptRightNode(right)) {
277	                        throw new SimpleParserException(
278	                                "Chain operator " + operator + " does not support right hand side token " + right.getToken(),
279	                                token.getToken().getIndex());
280	                    }
281	
282	                    // pop previous as we need to replace it with this other operator
283	                    stack.pop();
284	                    stack.push(token);
285	                    // this token is now the left for the next loop
286	                    left = token;
287	                }
288	
289	                // advantage after the right hand side
290	                i++;
291	            } else {
292	                // clear left
293	                left = null;
294	                stack.push(token);
295	            }
296	        }
297	
298	        nodes.clear();
299	        nodes.addAll(stack);
300	        // must reverse as it was added from a stack that is reverse
301	        Collections.reverse(nodes);
302	    }
303	
304	    protected void prepareOtherExpressions(List<SimpleNode> nodes) {
305	        Deque<SimpleNode> stack = new ArrayDeque<>();
306	
307	        SimpleNode left = null;
308	        for (int i = 0; i < nodes.size(); i++) {
309	            if (left == null) {
310	                left = i > 0 ? nodes.get(i - 1) : null;
311	            }
312	            SimpleNode token = nodes.get(i);
313	            SimpleNode right = i < nodes.size() - 1 ? nodes.get(i + 1) : null;
314	
315	            if (token instanceof OtherExpression other) {
316	                // remember the other operator
317	                String operator = other.getOperator().toString();
318	
319	                if (left == null) {
320	                    throw new SimpleParserException(
321	                            "Other operator " + operator + " has no left hand side token", token.getToken().getIndex());
322	                }
323	                if (!other.acceptLeftNode(left)) {
324	                    throw new SimpleParserException(
325	                            "Other operator " + operator + " does not support left hand side token " + left.getToken(),
326	                            token.getToken().getIndex());
327	                }
328	                if (right == null) {
329	                    throw new SimpleParserException(
330	                            "Other operator " + operator + " has no right hand side token", token.getToken().getIndex());
331	                }
332	                if (!other.acceptRightNode(right)) {
333	                    throw new SimpleParserException(
334	                            "Other operator " + operator + " does not support right hand side token " + right.getToken(),
335	                            token.getToken().getIndex());
336	                }
337	
338	                // pop previous as we need to replace it with this other operator
339	                stack.pop();
340	                stack.push(token);
341	                // advantage after the right hand side
342	                i++;
343	                // this token is now the left for the next loop
344	                left = token;
345	            } else {
346	                // clear left
347	                left = null;
348	                stack.push(token);
349	            }
350	        }
351	
352	        nodes.clear();
353	        nodes.addAll(stack);
354	        // must reverse as it was added from a stack that is reverse
355	        Collections.reverse(nodes);
356	    }
357	
358	    /**
359	     * Prepares ternary expressions.
360	     * <p/>
361	     * This process prepares the ternary expressions in the AST. This is done by linking the ternary operator (condition
362	     * ? trueValue : falseValue) with all three parts: condition, trueValue, and falseValue.
363	     * <p/>
364	     * The ternary operator consists of two tokens: ? and : We need to find the pattern: condition ? trueValue :
365	     * falseValue
366	     */
367	    protected void prepareTernaryExpressions(List<SimpleNode> nodes) {
368	        List<SimpleNode> answer = new ArrayList<>();
369	
370	        for (int i = 0; i < nodes.size(); i++) {
371	            SimpleNode token = nodes.get(i);
372	
373	            if (token instanceof TernaryExpression ternary && "?".equals(token.getToken().getText())) {
374	                // We found the ? operator
375	                // Get the condition (left side)
376	                if (answer.isEmpty()) {
377	                    throw new SimpleParserException(
378	                            "Ternary operator ? has no condition", token.getToken().getIndex());
379	                }
380	                SimpleNode condition = answer.remove(answer.size() - 1);
381	
382	                // Get the true value (right side of ?)
383	                if (i >= nodes.size() - 1) {
384	                    throw new SimpleParserException(
385	                            "Ternary operator ? has no true value", token.getToken().getIndex());
386	                }
387	                SimpleNode trueValue = nodes.get(++i);
388	
389	                // Find the : operator
390	                if (i >= nodes.size() - 1) {
391	                    throw new SimpleParserException(
392	                            "Ternary operator ? has no : operator", token.getToken().getIndex());
393	                }
394	                SimpleNode colonToken = nodes.get(++i);
395	                if (!(colonToken instanceof TernaryExpression) || !":".equals(colonToken.getToken().getText())) {
396	                    throw new SimpleParserException(
397	                            "Ternary operator ? must be followed by :", token.getToken().getIndex());
398	                }
399	
400	                // Get the false value (right side of :)
401	                if (i >= nodes.size() - 1) {
402	                    throw new SimpleParserException(
403	                            "Ternary operator : has no false value", token.getToken().getIndex());
404	                }
405	                SimpleNode falseValue = nodes.get(++i);
406	
407	                // Link all parts to the ternary expression
408	                if (!ternary.acceptCondition(condition)) {
409	                    throw new SimpleParserException(
410	                            "Ternary operator does not support condition token " + condition.getToken(),
411	                            token.getToken().getIndex());
412	                }
413	                if (!ternary.acceptTrueValue(trueValue)) {
414	                    throw new SimpleParserException(
415	                            "Ternary operator does not support true value token " + trueValue.getToken(),
416	                            token.getToken().getIndex());
417	                }
418	                if (!ternary.acceptFalseValue(falseValue)) {
419	                    throw new SimpleParserException(
420	                            "Ternary operator does not support false value token " + falseValue.getToken(),
421	                            token.getToken().getIndex());
422	                }
423	
424	                answer.add(ternary);
425	            } else {
426	                answer.add(token);
427	            }
428	        }
429	
430	        nodes.clear();
431	        nodes.addAll(answer);
432	    }
433	
434	    // --------------------------------------------------------------
435	    // grammar
436	    // --------------------------------------------------------------
437	
438	    /**
439	     * Accept the given token.
440	     * <p/>
441	     * This is to be used by the grammar to accept tokens and then continue parsing using the grammar, such as a
442	     * function grammar.
443	     *
444	     * @param  accept the token
445	     * @return        <tt>true</tt> if accepted, <tt>false</tt> otherwise.
446	     */
447	    protected boolean accept(TokenType accept) {
448	        return token == null || token.getType().getType() == accept;
449	    }
450	
451	    /**
452	     * Expect any of the given token(s)
453	     *
454	     * @param  expect                the token(s) to expect
455	     * @throws SimpleParserException is thrown if the token is not as expected
456	     */
457	    protected void expect(TokenType... expect) throws SimpleParserException {
458	        if (token == null) {
459	            throw new SimpleParserException("expected any symbol " + Arrays.asList(expect) + " but reached eol", previousIndex);
460	        }
461	        for (TokenType target : expect) {
462	            if (token.getType().getType() == target) {
463	                return;
464	            }
465	        }
466	        // use the previous index as that is where the problem is
467	        throw new SimpleParserException(
468	                "expected any symbol " + Arrays.asList(expect) + " but was " + token.getType().getType(), previousIndex);
469	    }
470	
471	    /**
472	     * Expect a given token
473	     *
474	     * @param  expect                the token to expect
475	     * @throws SimpleParserException is thrown if the token is not as expected
476	     */
477	    protected void expect(TokenType expect) throws SimpleParserException {
478	        if (token != null && token.getType().getType() == expect) {
479	            return;
480	        } else if (token == null) {
481	            // use the previous index as that is where the problem is
482	            throw new SimpleParserException("expected symbol " + expect + " but reached eol", previousIndex);
483	        } else {
484	            // use the previous index as that is where the problem is
485	            throw new SimpleParserException(
486	                    "expected symbol " + expect + " but was " + token.getType().getType(), previousIndex);
487	        }
488	    }
489	
490	    /**
491	     * Expect and accept a given number of tokens in sequence.
492	     * <p/>
493	     * This is used to accept whitespace or string literals.
494	     *
495	     * @param expect the token to accept
496	     */
497	    protected void expectAndAcceptMore(TokenType expect) {
498	        expect(expect);
499	
500	        while (!token.getType().isEol() && token.getType().getType() == expect) {
501	            nextToken();
502	        }
503	    }
504	
505	}
